import { defineConfig } from 'vite';
import { join } from 'node:path';
import { LANGS, ROUTES } from './site/content.js';

// One HTML entry per route and language (generated by scripts/generate.mjs).
const input = Object.fromEntries(
  Object.entries(ROUTES).flatMap(([key, byLang]) =>
    LANGS.map((lang) => [`${key}-${lang}`, join(import.meta.dirname, byLang[lang].replace(/^\//, ''), 'index.html')])
  )
);

export default defineConfig({
  build: { chunkSizeWarningLimit: 700, rollupOptions: { input } },
});
